css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .unir-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 10px 40px; align-items: start;}
.mz .unir-col{display: flex; flex-direction: column; gap: 8px;}
.mz .unir-item{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 6px 10px; text-align: center; font-size: 13.5px; font-weight: 700;}
.mz .cal-wrap{display: grid; grid-template-columns: 1fr auto; gap: 16px; align-items: center;}
.mz .cal-tabla{width: 100%; border-collapse: collapse;}
.mz .cal-tabla th,.mz .cal-tabla td{border: 1.5px solid var(--bosque); padding: 4px 2px; text-align: center; font-size: 12px; font-weight: 600; height: 26px;}
.mz .cal-tabla th{background: #f4f4f4; font-weight: 700; font-size: 10.5px;}
.mz .cal-preguntas{display: flex; flex-direction: column; gap: 8px; font-size: 12.5px;}
.mz .cal-preg{display: flex; align-items: center; gap: 6px;}
.mz .cal-hueco{display: inline-block; width: 42px; height: 26px; border: 1.5px solid var(--bosque); border-radius: 5px;}
.mz .serie-bloque{display: flex; flex-direction: column; gap: 6px;}
.mz .serie-fila{display: grid; grid-template-columns: repeat(5, 1fr); gap: 6px;}
.mz .serie-caja{border: 1.5px solid var(--bosque); border-radius: 6px; min-height: 36px; display: flex; align-items: center; justify-content: center; font-size: 12.5px; font-weight: 700; text-align: center; padding: 3px;}
.mz .serie-caja.lleno{background: #f4f4f4;}
.mz .prob-lista{display: flex; flex-direction: column; gap: 8px;}
.mz .prob{font-size: 13px; line-height: 1.5;}
.mz .hueco-linea{display: inline-block; min-width: 105px; border-bottom: 1.5px solid var(--bosque); height: 18px; vertical-align: bottom; margin: 0 3px;}
.mz .prob{line-height: 1.875 !important;}
